        "invoice_date": "2026-01-15",
        "partner_id": partner_id,
        "untaxed_amount": round(sum(x["untaxed_amount"] for x in lines), 2),
        "tax_amount": round(sum(x["tax_amount"] for x in lines), 2),
        "total": round(sum(x["total"] for x in lines), 2),
        "lines": lines,
    } | changes


